-- PREPARED ONLY. Requires separate approval before executing on the mapped shared database.
-- Generated from the two reviewed upgrade functions; no application startup or historical adoption.
BEGIN;
SET LOCAL search_path = public, pg_catalog;
SET LOCAL lock_timeout = '1s';
SET LOCAL statement_timeout = '10s';
SET LOCAL idle_in_transaction_session_timeout = '15s';
-- Serializes this release across affected writers; reads remain possible until ALTER needs its lock.
LOCK TABLE public.alembic_version, public.profiles, public.credit_transactions,
 public.live_session_participants, public.global_pricing_config IN SHARE ROW EXCLUSIVE MODE;
DO $$
BEGIN
 IF (SELECT array_agg(version_num::text ORDER BY version_num) FROM public.alembic_version)
    IS DISTINCT FROM ARRAY['6b8bb9b66da7','avatar_url_text_001','e1a0c5f2b7d4']::text[] THEN
  RAISE EXCEPTION 'Unexpected version lineage; stop and reconcile';
 END IF;
 IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND
  (table_name,column_name) IN (('profiles','spend_only_credits'),('credit_transactions','spend_only_amount'),
   ('credit_transactions','refund_of_transaction_id'),('live_session_participants','payment_credit_transaction_id'),
   ('global_pricing_config','credit_package_bonuses')))
 OR to_regclass('public.monthly_leaderboard_archives') IS NOT NULL
 OR to_regclass('public.ix_credit_transactions_refund_of_transaction_id') IS NOT NULL THEN
  RAISE EXCEPTION 'Partial or already applied schema; stop and reconcile';
 END IF;
END $$;
ALTER TABLE live_session_participants ADD COLUMN payment_credit_transaction_id VARCHAR(36);

ALTER TABLE profiles ADD COLUMN spend_only_credits FLOAT DEFAULT '0' NOT NULL;

ALTER TABLE credit_transactions ADD COLUMN spend_only_amount FLOAT DEFAULT '0' NOT NULL;

ALTER TABLE credit_transactions ADD COLUMN refund_of_transaction_id VARCHAR(36);

CREATE INDEX ix_credit_transactions_refund_of_transaction_id ON credit_transactions (refund_of_transaction_id);

ALTER TABLE global_pricing_config ADD COLUMN credit_package_bonuses JSON;

CREATE TABLE monthly_leaderboard_archives (
    year INTEGER NOT NULL, 
    month INTEGER NOT NULL, 
    archived_count INTEGER NOT NULL, 
    completed_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    PRIMARY KEY (year, month)
);


DO $$
DECLARE affected integer;
BEGIN
 UPDATE public.alembic_version SET version_num='monthly_archive_replay_001'
 WHERE version_num='e1a0c5f2b7d4';
 GET DIAGNOSTICS affected = ROW_COUNT;
 IF affected <> 1 THEN RAISE EXCEPTION 'Version compare-and-swap failed'; END IF;
 IF (SELECT array_agg(version_num::text ORDER BY version_num) FROM public.alembic_version)
    IS DISTINCT FROM ARRAY['6b8bb9b66da7','avatar_url_text_001','monthly_archive_replay_001']::text[] THEN
  RAISE EXCEPTION 'Unexpected resulting version lineage';
 END IF;
END $$;
COMMIT;
-- Verify separately in BEGIN READ ONLY / ROLLBACK:
-- version rows, five column types/defaults/nullability, refund index, archive PK(year,month).
-- No customer rows, historical snapshot adoption, financial correction or destructive downgrade.
